import{_ as a,K as i,a as r,c as n,ac as e,q as l}from"./chunks/framework.BSuaGltH.js";const x=JSON.parse('{"title":"进制 & 转换","description":"按位分组与除基取余进行进制转换，并核对练习结果。","frontmatter":{"title":"进制 & 转换","description":"进制 & 转换","sources":[{"repository":"jekyall_blog","file":"_posts/Language/C/2023-05-23-binary.md","date":"Fri Jan 06 2023 09:58:36 GMT+0800 (中国标准时间)"}],"showdocs":{"topics":[{"id":"execution","title":"数据表示与程序执行","link":"/topics/execution/"},{"id":"c","title":"C","link":"/topics/c/"}],"kind":"模型代价与规范","scope":"general","audience":"general","group":"原理与设计","summary":"按位分组与除基取余进行进制转换，并核对练习结果。","status":"active","related":[{"title":"程序执行、调用栈与模型边界","link":"/principles/execution/execution-model","kind":"表示与执行状态","scope":"general","audience":"general"},{"title":"栈机解释器与表达式编译练习","link":"/principles/execution/application","kind":"表达式栈机","scope":"general","audience":"general"},{"title":"IEEE 754 浮点数表示与比较","link":"/principles/execution/ieee","kind":"模型代价与规范","scope":"general","audience":"general"},{"title":"C 定长池：布局、归还与故障边界","link":"/programming/c/allocator-contracts","kind":"知识专题","scope":"general","audience":"general"},{"title":"C 定长分配器完整实践：为 PMR 提供存储","link":"/programming/c/plus/practice/allocator-application","kind":"开发实践","scope":"general","audience":"general"}],"prev":{"text":"栈机解释器与表达式编译练习","link":"/principles/execution/application"},"next":{"text":"IEEE 754 浮点数表示与比较","link":"/principles/execution/ieee"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"栈机解释器与表达式编译练习","link":"/principles/execution/application"},"next":{"text":"IEEE 754 浮点数表示与比较","link":"/principles/execution/ieee"}},"headers":[],"relativePath":"principles/execution/binary.md","filePath":"principles/execution/binary.md"}'),o={name:"principles/execution/binary.md"};function s(c,t,p,h,u,m){const d=i("Mermaid");return r(),n("div",null,[t[0]||(t[0]=e('<h1 id="进制-转换" tabindex="-1">进制 &amp; 转换 <a class="header-anchor" href="#进制-转换" aria-label="Permalink to &quot;进制 &amp; 转换&quot;">​</a></h1><h2 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to &quot;简介&quot;">​</a></h2><p>进制用基数和各位权值表示数值。计算机常见二、八、十、十六进制；转换进制改变写法，不改变数值。</p><h2 id="分类" tabindex="-1">分类 <a class="header-anchor" href="#分类" aria-label="Permalink to &quot;分类&quot;">​</a></h2><table tabindex="0"><thead><tr><th>进制</th><th>基数</th><th>数字</th><th>常见用途</th></tr></thead><tbody><tr><td>二进制</td><td>2</td><td>0、1</td><td>位状态和机器数据</td></tr><tr><td>八进制</td><td>8</td><td>0–7</td><td>Unix 文件权限</td></tr><tr><td>十进制</td><td>10</td><td>0–9</td><td>日常计数</td></tr><tr><td>十六进制</td><td>16</td><td>0–9、A–F</td><td>内存、颜色和字节数据</td></tr></tbody></table><h2 id="计算机中主要用途" tabindex="-1">计算机中主要用途 <a class="header-anchor" href="#计算机中主要用途" aria-label="Permalink to &quot;计算机中主要用途&quot;">​</a></h2><p>八进制一位对应三位二进制，十六进制一位对应四位二进制，因此便于压缩展示位模式。C 中八进制整数字面量通常以 0 开头，十六进制以 0x 开头；其他语言的字面量语法需分别确认。</p><h2 id="之间转换" tabindex="-1">之间转换 <a class="header-anchor" href="#之间转换" aria-label="Permalink to &quot;之间转换&quot;">​</a></h2><p>以十进制26转二进制为例，下图记录每次除2的余数。余数先得到低位，因此需倒序读取为11010；正向拼接01011会得到错误的值。</p>',9)),l(d,{source:"Zmxvd2NoYXJ0IFRECiBBWyIyNumZpDLvvJrllYYxM+S9mTAiXSAtLT4gQlsiMTPpmaQy77ya5ZWGNuS9mTEiXQogQiAtLT4gQ1siNumZpDLvvJrllYYz5L2ZMCJdCiBDIC0tPiBEWyIz6ZmkMu+8muWVhjHkvZkxIl0KIEQgLS0+IEVbIjHpmaQy77ya5ZWGMOS9mTEiXQogRSAtLT4gRlsi5YCS6K+75L2Z5pWw77yaMTEwMTAiXQo="}),t[1]||(t[1]=e('<ul><li><strong>二进制转八进制或十六进制</strong>：从右往左按三位或四位分组，最左不足位补零，再把每组转换为一个目标数字。例如二进制 110100111：按 110 100 111 得八进制 647，按 0001 1010 0111 得十六进制 1A7。</li><li><strong>八进制或十六进制转二进制</strong>：每位分别展开成三位或四位，再连接。八进制与十六进制互转时，先转二进制再重新分组；不能直接把每个八进制数字当成四位二进制。</li><li><strong>十进制转其他整数进制</strong>：连续除以目标基数，记录余数，直到商为零；余数倒序排列。零本身写作 0。</li><li><strong>其他进制转十进制</strong>：从右起，第 i 位乘以基数的 i 次幂后求和。例如十六进制 AB = 10 × 16 + 11 = 171。</li></ul><h3 id="练习" tabindex="-1">练习 <a class="header-anchor" href="#练习" aria-label="Permalink to &quot;练习&quot;">​</a></h3><p>下表保留原练习，修正分组与结果中的算术错误。数字的进制由列名指定，十六进制统一使用大写字母。</p><p>先独立转换二进制10101010、八进制755、十进制128、十六进制1A，以及下表其余四题；再展开答案核对。</p><details class="details custom-block"><summary>转换结果与参考步骤</summary><table tabindex="0"><thead><tr><th>原题</th><th>二进制</th><th>八进制</th><th>十进制</th><th>十六进制</th></tr></thead><tbody><tr><td>二进制 10101010</td><td>10101010</td><td>252</td><td>170</td><td>AA</td></tr><tr><td>八进制 755</td><td>111101101</td><td>755</td><td>493</td><td>1ED</td></tr><tr><td>十进制 128</td><td>10000000</td><td>200</td><td>128</td><td>80</td></tr><tr><td>十六进制 1A</td><td>11010</td><td>32</td><td>26</td><td>1A</td></tr><tr><td>二进制 1101010111011111</td><td>1101010111011111</td><td>152737</td><td>54751</td><td>D5DF</td></tr><tr><td>八进制 654</td><td>110101100</td><td>654</td><td>428</td><td>1AC</td></tr><tr><td>十进制 1024</td><td>10000000000</td><td>2000</td><td>1024</td><td>400</td></tr><tr><td>十六进制 FE</td><td>11111110</td><td>376</td><td>254</td><td>FE</td></tr></tbody></table><p>例：八进制 755 展开为 111 101 101，重新按四位分组为 0001 1110 1101，即十六进制 1ED。</p></details><p>以上算法和表格针对非负整数；带符号编码与小数转换另需规则。本轮仅逐项静态复算，没有执行转换程序。</p>',6))])}const _=a(o,[["render",s]]);export{x as __pageData,_ as default};
